
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_ssb_sw_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_ssb_sw", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.390960014719323e+00, -4.303434411901238e+00, -4.180935165383427e+00, -4.011579553897803e+00, -3.781620591676567e+00, -3.477596782008028e+00, -3.091542175001960e+00, -2.630529826419717e+00, -2.124541597787029e+00, -1.607081238568157e+00, -1.085012804430073e+00, -7.238791129188525e-01, -6.205378264691737e-01, -5.041913519167581e-01, -3.687195684328707e-01, -2.428553679648997e-01, -1.332547672494686e-01, -4.950566054769141e-02, -1.081173500605318e-02, -1.216201113652568e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


